<?php
require __DIR__.'/config.php';$me=require_auth();$cid=$me['customer_id'];try{sync_approval_messages(db(),(int)$cid,(int)$me['id']);}catch(Throwable $x){}
$s=db()->prepare("SELECT a.account_id,a.account_number,a.account_title,a.balance,a.currency,a.status,t.type_name FROM account_holders h JOIN accounts a ON a.account_id=h.account_id JOIN account_types t ON t.account_type_id=a.account_type_id WHERE h.customer_id=? ORDER BY h.holder_role='primary' DESC,a.account_id DESC");$s->execute([$cid]);$accounts=$s->fetchAll();$ids=array_map('intval',array_column($accounts,'account_id'));$tx=[];
if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT transaction_id,reference_number,account_id,transaction_type,amount,status,created_at FROM transactions WHERE account_id IN ($marks) ORDER BY created_at DESC,transaction_id DESC LIMIT 5");$s->execute($ids);$tx=$s->fetchAll();}
$sum=array_sum(array_map(fn($a)=>(float)$a['balance'],$accounts));$s=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$s->execute([$me['id']]);$unread=(int)$s->fetchColumn();$s=db()->prepare('SELECT type,message,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC,notification_id DESC LIMIT 4');$s->execute([$me['id']]);$recentNotifications=$s->fetchAll();$pending=count(array_filter($accounts,fn($a)=>$a['status']==='pending'));$kyc=db()->prepare('SELECT kyc_status FROM customers WHERE customer_id=?');$kyc->execute([$cid]);$kycStatus=$kyc->fetchColumn();
render_start('Dashboard');
?>
<section class="page-heading"><div class="eyebrow dark">Your BankEase</div><h1>Welcome, <?=e($me['name'])?>.</h1><p>Here’s a clear view of your accounts and recent activity.</p><div class="actions"><a class="button navy" href="<?=e(url('new_account.php'))?>">Open another account</a><a class="button pale" href="<?=e(url('loans.php'))?>">Apply for a loan</a><a class="button pale" href="<?=e(url('transfer.php'))?>">Make a transfer</a><a class="button pale" href="<?=e(url('cards.php'))?>">Request a card</a><a class="button pale" href="<?=e(url('notifications.php'))?>">Notifications</a></div></section>
<section class="stats"><article class="stat"><span>Accounts</span><strong><?=count($accounts)?></strong></article><article class="stat"><span>Total held balance</span><strong>BDT <?=e(number_format($sum,2))?></strong></article><article class="stat"><span>Unread alerts</span><strong><?=$unread?></strong></article><article class="stat"><span>Pending accounts</span><strong><?=$pending?></strong></article></section>
<div class="section-heading"><h2>My accounts</h2><a href="<?=e(url('accounts.php'))?>">View all →</a></div>
<?php if($accounts):?><div class="account-grid"><?php foreach(array_slice($accounts,0,3) as $a):?><article class="account-card"><div class="account-top"><span class="eyebrow dark"><?=e($a['type_name'])?></span><span class="badge"><?=e(ucfirst($a['status']))?></span></div><h3><?=e($a['account_title'])?></h3><p class="account-number">•••• <?=e(substr($a['account_number'],-4))?></p><strong class="balance"><?=e($a['currency'])?> <?=e(number_format((float)$a['balance'],2))?></strong><a href="<?=e(url('account.php?id='.(int)$a['account_id']))?>">Account details →</a></article><?php endforeach;?></div><?php else:?><div class="empty">No accounts are linked to your profile yet. KYC review status: <?=e(ucfirst((string)$kycStatus))?>.</div><?php endif;?>
<div class="section-heading"><h2>Recent activity</h2><a href="<?=e(url('activity.php'))?>">View statement →</a></div>
<?php if($tx):?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th>Type</th><th>Status</th><th>Amount</th></tr></thead><tbody><?php foreach($tx as $t):?><tr><td><?=e($t['created_at'])?></td><td><a href="<?=e(url('transaction.php?id='.(int)$t['transaction_id']))?>"><?=e($t['reference_number'])?></a></td><td><?=e(ucwords(str_replace('_',' ',$t['transaction_type'])))?></td><td><?=e(ucfirst($t['status']))?></td><td>BDT <?=e(number_format((float)$t['amount'],2))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No transactions to show yet.</div><?php endif;?>
<div class="section-heading"><h2>Latest notifications</h2><a href="<?=e(url('notifications.php'))?>">View all notifications →</a></div><?php if($recentNotifications):?><div class="dashboard-notifications"><?php foreach($recentNotifications as $n):?><article class="dashboard-notification <?=$n['is_read']?'read':'unread'?>"><div><strong><?=e(ucwords(str_replace('_',' ',$n['type'])))?></strong><time><?=e($n['created_at'])?></time><?php if(!$n['is_read']):?><span class="badge">New</span><?php endif;?></div><p><?=e($n['message'])?></p></article><?php endforeach;?></div><?php else:?><div class="empty">No notifications yet.</div><?php endif;?>
<div class="section-heading"><h2>Loans</h2><a href="<?=e(url('loans.php'))?>">View loan applications →</a></div>
<?php render_end();?>
